'use client';
import{jsx as _jsx}from"react/jsx-runtime";
import{useEffect,useLayoutEffect,useRef}from'react';
import{ARRIVE,S}from'../../core/spring.js';
import{enter}from'../../dom/index.js';
import{customizePart}from'../customization.js';
const useIso=typeof window==='undefined'?useEffect:useLayoutEffect;
const cfgOf=(p)=>(typeof p==='string'?S[p]:p);
export function computeStaggerDelays(count,stepMs=40,budgetMs=300){
const n=Math.max(0,Math.floor(count));
if(n===0)
return[];
if(n===1)
return[0];
const safeBudget=Math.max(0,budgetMs);
const safeStep=Math.max(0,stepMs);
const perItem=Math.min(safeStep,safeBudget/(n-1));
return Array.from({length:n},(_,i)=>+(i*perItem).toFixed(4));
}
export function StaggerGroup({className,slotProps,budget=300,delay=40,distance=6,preset='base',triggerKey,motion=true,disabled=false,children,}){
const isDisabled=disabled||motion===false;
const rootRef=useRef(null);
useIso(()=>{
const root=rootRef.current;
if(!root||isDisabled)
return;
const items=Array.from(root.children).filter((n)=>n instanceof HTMLElement);
if(items.length===0)
return;
const clampedBudget=Math.min(300,Math.max(0,budget));
const stepSeconds=items.length>1?Math.min(Math.max(0,delay),clampedBudget/(items.length-1))/1000:0;
return enter(items,{
stagger:stepSeconds,
cfg:cfgOf(preset),
from:{x:0,y:distance,opacity:ARRIVE,scale:1,blur:0},
});
},[triggerKey,isDisabled,budget,delay,distance]);
return(_jsx("div",{ref:rootRef,"data-motion":isDisabled?'off':'on',className:"cieo cieo-stagger-group",...customizePart(slotProps?.root,'cieo cieo-stagger-group',undefined,className),children:children}));
}
